/* The existing styles for the Back to Top button */
  #progress {
    position: fixed;
    bottom: 30px;
    right: 30px;
    height: 50px;
    width: 50px;
    display: none;
    place-items: center;
    border-radius: 30%;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);
    cursor: pointer;
  }
  #progress::before {
    content: "↑"; /* The content of the pseudo-element, which displays the arrow symbol */
    display: grid;
    height: calc(100% - 10px);
    width: calc(100% - 10px);
    background-color: #2b3546;
    border-radius: 30%;
    place-items: center;
    font-size: 20px;
    color: #ffffff;
  }

